(function(){document.addEventListener("DOMContentLoaded",()=>{document.addEventListener("joomla-dialog:open",t=>{if(t.target&&t.target.classList.contains("preview-certificate-dialog")){const o=t.target.JoomlaDialogTrigger.closest("tr");if(o){const e=o.querySelector("input.form-check-input");e&&e.checked&&e.click()}}})})})();
